import {MfeInitModule} from './mfe-init-module';

/**
 * This is the type of the object you get when you call the loadComponent()
 * function to load a PowerSchool MFE.
 *
 * NOTE: That function actually returns the "any" type, so you have to
 *       specify this type manually to downcast it.
 */
export type ModuleFederationLoaderFunction = () => Promise<ModuleFederationModule>;

/**
 * This is the type of the module object returned by the Module Federation
 * loader function when loading a PowerSchool MFE.
 */
export interface ModuleFederationModule {
    default: MfeInitModule;
}
